
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_vmt_pbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_vmt_pbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.304567647851922e+00, -4.222914721696856e+00, -4.108617082547750e+00, -3.950534394106262e+00, -3.735650662394563e+00, -3.450767159945634e+00, -3.086434704054389e+00, -2.643922079933966e+00, -2.143757130166212e+00, -1.624111580780508e+00, -1.101997436710803e+00, -7.105314423066433e-01, -6.021783392006138e-01, -5.018089763651289e-01, -3.723431272816147e-01, -2.475933690466868e-01, -1.397555593636516e-01, -4.847484299692945e-02, -6.035916486726347e-03, -6.741774113089777e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


